package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.CreatorCollector;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_addPropertyCreator_TriageGen1Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDescription;
    private MapperConfig<?> mapperConfig;
    private AnnotatedWithParams mockCreator;

    @Before
    public void setUp() {
        beanDescription = mock(BeanDescription.class);
        mapperConfig = mock(MapperConfig.class);
        mockCreator = mock(AnnotatedWithParams.class);
        // CreatorCollector constructor is public
        creatorCollector = new CreatorCollector(beanDescription, mapperConfig);

        // Note: verifyNonDup is protected. In a real scenario, if it's part of the same package 
        // or we use a spy, we can handle it. Since we want to test addPropertyCreator logic, 
        // we assume verifyNonDup passes or we mock the behavior if possible.
        // However, since we cannot easily mock a protected method of the class under test 
        // without a Spy, we will use a Spy to bypass verifyNonDup's potential side effects.
        creatorCollector = spy(new CreatorCollector(beanDescription, mapperConfig));
        doNothing().when(creatorCollector).verifyNonDup(any(), anyInt(), anyBoolean());
    }

    @Test
    public void testAddPropertyCreator_SingleProperty() {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("prop1");
        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1};

        creatorCollector.addPropertyCreator(mockCreator, true, properties);

        // Verify no exception thrown and logic completes
        verify(creatorCollector).verifyNonDup(mockCreator, 1, true); // C_PROPS is 1 based on typical Jackson internal constants
    }

    @Test
    public void testAddPropertyCreator_MultipleProperties_Success() {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("prop1");
        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("prop2");

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2};

        creatorCollector.addPropertyCreator(mockCreator, false, properties);

        verify(creatorCollector).verifyNonDup(mockCreator, 1, false);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAddPropertyCreator_DuplicateNames_ThrowsException() {
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("duplicate");
        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("duplicate");

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2};

        creatorCollector.addPropertyCreator(mockCreator, true, properties);
    }

    @Test
    public void testAddPropertyCreator_InjectablesWithEmptyName_AreSkipped() {
        // Property 1: Normal
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("normal");

        // Property 2: Injectable with empty name (Should be skipped)
        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("");
        when(prop2.getInjectableValueId()).thenReturn("someId");

        // Property 3: Duplicate of Property 1 (To check if skip works)
        SettableBeanProperty prop3 = mock(SettableBeanProperty.class);
        when(prop3.getName()).thenReturn("normal");

        // If prop2 is skipped, prop3 will trigger duplicate with prop1.
        // If prop2 is NOT skipped, prop3 will trigger duplicate with prop2 (but prop2 has empty name).
        // Actually, the logic is: if name is "" and has injectable ID, skip.
        // So if we have ["normal", "", "normal"], the second "normal" (index 2) will collide with index 0.

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2, prop3};

        try {
            creatorCollector.addPropertyCreator(mockCreator, true, properties);
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("Duplicate creator property \"normal\" (index 0 vs 2)"));
        }
    }

    @Test
    public void testAddPropertyCreator_InjectablesWithEmptyNameAndNoId_NotSkipped() {
        // This tests the branch where name.length() == 0 but injectableValueId is null
        SettableBeanProperty prop1 = mock(SettableBeanProperty.class);
        when(prop1.getName()).thenReturn("");
        when(prop1.getInjectableValueId()).thenReturn(null);

        SettableBeanProperty prop2 = mock(SettableBeanProperty.class);
        when(prop2.getName()).thenReturn("");
        when(prop2.getInjectableValueId()).thenReturn(null);

        SettableBeanProperty[] properties = new SettableBeanProperty[]{prop1, prop2};

        // Should throw exception because they are treated as duplicates of ""
        try {
            creatorCollector.addPropertyCreator(mockCreator, true, properties);
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("Duplicate creator property \"\""));
        }
    }

    @Test
    public void testAddPropertyCreator_EmptyPropertiesArray() {
        SettableBeanProperty[] properties = new SettableBeanProperty[0];
        creatorCollector.addPropertyCreator(mockCreator, true, properties);
        verify(creatorCollector).verifyNonDup(mockCreator, 1, true);
    }
}
